/**
 * buildRoadScenarioDiagram.mjs
 *
 * Draws the road-scene diagrams used by behavioural subtopics, and rasterises
 * each one to PNG ready for upload.
 *
 * Why drawn rather than generated by an image model: in these subtopics the
 * picture IS the question. If the green arrow lands on the wrong car, the
 * learner is taught the opposite of the law. Every coordinate here is
 * deliberate, so the arrow cannot drift between one diagram and the next. It
 * also keeps a scene near 70 KB rather than the several hundred an image model
 * returns, which matters on the phones these learners actually use.
 *
 * Why PNG as well as SVG: React Native's <Image> cannot render SVG and the app
 * does not bundle react-native-svg. The SVG stays the source of truth; the PNG
 * is what ships. Change a colour or an arrow here, re-run, re-upload.
 *
 * Lane sides follow RIGHT-HAND traffic. Northbound keeps to the east half of
 * the road, southbound to the west. Those two positions are named constants
 * rather than raw numbers on purpose: the first draft of this diagram had the
 * cars on the wrong sides, which reads as British traffic and quietly teaches
 * the wrong road position.
 *
 * Usage:
 *   node scripts/buildRoadScenarioDiagram.mjs
 *   node scripts/buildRoadScenarioDiagram.mjs --out <directory>
 */

import { writeFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

const require    = createRequire(import.meta.url);
const __dirname  = dirname(fileURLToPath(import.meta.url));
const ROOT       = join(__dirname, '..');

// ─── Palette ──────────────────────────────────────────────────────────────────

const C = {
  grass:  '#7cc576',
  road:   '#5b6169',
  kerb:   '#e5e7eb',
  line:   '#f8fafc',
  go:     '#15803d',   // the vehicle with priority
  wait:   '#b91c1c',   // the vehicle that must give way
  glass:  '#cfe8f5',
  badge:  '#111827',
  tyre:   '#1f2937',
};

/** Car body colours, each with a matching darker outline. */
const CARS = {
  yellow: { body: '#f2b705', edge: '#8a6a00' },
  green:  { body: '#1f9d55', edge: '#0b5c31' },
  blue:   { body: '#2563eb', edge: '#12327a' },
  white:  { body: '#f1f5f9', edge: '#64748b' },
  red:    { body: '#dc2626', edge: '#7f1d1d' },
  silver: { body: '#cbd5e1', edge: '#64748b' },
  // Every other colour here pairs a body with a DARKER edge for definition.
  // Black is already the darkest possible body, so it inverts that: a
  // lighter grey edge is what actually gives it a visible outline, both
  // against its own fill and against the (also dark) road.
  black:  { body: '#18181b', edge: '#6b7280' },
};

// ─── Car ──────────────────────────────────────────────────────────────────────

/**
 * A car seen from above, drawn nose-up and then rotated into place.
 *
 * @param x,y      centre of the car
 * @param heading  degrees clockwise; 0 = nose up (north), 90 = nose right
 * @param colour   key of CARS
 * @param indicate 'left' | 'right' | null — lights that indicator
 * @param scale    1 is a car roughly 56x104
 */
function car({ x, y, heading = 0, colour = 'white', indicate = null, scale = 1 }) {
  const { body, edge } = CARS[colour] ?? CARS.white;

  // Nose at y=-52, tail at y=+52, narrower at the front like a real car seen
  // from above — that taper is what stops it reading as a plain rectangle.
  const outline = 'M 0,-52 C 13,-52 23,-47 25,-38 L 27,28 C 27,42 21,52 10,52 '
                + 'L -10,52 C -21,52 -27,42 -27,28 L -25,-38 C -23,-47 -13,-52 0,-52 Z';

  const indicator = side => {
    if (indicate !== side) return '';
    const ix = side === 'left' ? -21 : 21;
    return `<circle cx="${ix}" cy="-44" r="6.5" fill="#ff8c00" stroke="${edge}" stroke-width="1.5"/>`
         + `<circle cx="${ix}" cy="-44" r="11" fill="none" stroke="#ff8c00" stroke-width="2" opacity="0.5"/>`;
  };

  return `
  <g transform="translate(${x} ${y}) rotate(${heading}) scale(${scale})">
    <g fill="${C.tyre}">
      <rect x="-31" y="-34" width="9" height="22" rx="4"/>
      <rect x="22"  y="-34" width="9" height="22" rx="4"/>
      <rect x="-31" y="12"  width="9" height="22" rx="4"/>
      <rect x="22"  y="12"  width="9" height="22" rx="4"/>
    </g>

    <path d="${outline}" fill="${body}" stroke="${edge}" stroke-width="3" stroke-linejoin="round"/>

    <rect x="-31" y="-24" width="6" height="9" rx="2.5" fill="${body}" stroke="${edge}" stroke-width="1.5"/>
    <rect x="25"  y="-24" width="6" height="9" rx="2.5" fill="${body}" stroke="${edge}" stroke-width="1.5"/>

    <path d="M -17,-26 L 17,-26 L 14,-12 L -14,-12 Z" fill="${C.glass}"/>
    <rect x="-15" y="-12" width="30" height="26" rx="3" fill="${body}" stroke="${edge}" stroke-width="1.5"/>
    <path d="M -14,14 L 14,14 L 17,27 L -17,27 Z" fill="${C.glass}"/>

    <rect x="-19" y="-50" width="11" height="6" rx="3" fill="#fff8dc" stroke="${edge}" stroke-width="1.2"/>
    <rect x="8"   y="-50" width="11" height="6" rx="3" fill="#fff8dc" stroke="${edge}" stroke-width="1.2"/>
    <rect x="-19" y="44"  width="11" height="6" rx="3" fill="#ef4444" stroke="${edge}" stroke-width="1.2"/>
    <rect x="8"   y="44"  width="11" height="6" rx="3" fill="#ef4444" stroke="${edge}" stroke-width="1.2"/>

    ${indicator('left')}${indicator('right')}
  </g>`;
}


/** The numbered disc that lets a spoken question say "car number two". */
function badge({ x, y, n }) {
  return `
  <g>
    <circle cx="${x}" cy="${y}" r="16" fill="${C.badge}"/>
    <text x="${x}" y="${y + 6}" font-family="Arial, Helvetica, sans-serif" font-size="19"
          font-weight="bold" fill="#ffffff" text-anchor="middle">${n}</text>
  </g>`;
}

/**
 * A give-way sign on its post: a downward-pointing triangle, red rim, pale
 * centre.
 *
 * ⚠️ No lettering, ever. The app is used by Amharic speakers across many
 * countries and a word painted on a sign is a word most of its learners cannot
 * read — the shape and the colour have to carry the whole meaning, exactly as
 * they do on a real road. The narration says what the sign means; the picture
 * only shows what it looks like.
 */
function giveWaySign({ x, y, scale = 1 }) {
  return `
  <g transform="translate(${x} ${y}) scale(${scale})">
    <rect x="-3" y="0" width="6" height="46" fill="#9ca3af" stroke="#6b7280" stroke-width="1.5"/>
    <path d="M -30,-46 L 30,-46 L 0,4 Z" fill="#ffffff" stroke="#c81e1e" stroke-width="9" stroke-linejoin="round"/>
  </g>`;
}

/**
 * The level-crossing warning sign: an upward-pointing red triangle (the
 * general warning-sign shape, apex up — the mirror of giveWaySign()'s
 * apex-down triangle) with a plain black train pictogram inside, no
 * lettering. Modelled on the real sign (a red triangle with a black train
 * silhouette) without copying its file — this app draws its own simplified
 * version of every sign, the same as every other one in this file.
 *
 * This is the basic crossing-designation sign every level crossing has by
 * law, distinct from the active control devices (a barrier, a flashing
 * light, a stop sign) that a specific crossing may or may not also have.
 */
function railwayWarningSign({ x, y, scale = 1 }) {
  return `
  <g transform="translate(${x} ${y}) scale(${scale})">
    <rect x="-3" y="4" width="6" height="46" fill="#9ca3af" stroke="#6b7280" stroke-width="1.5"/>
    <path d="M 0,-46 L 30,4 L -30,4 Z" fill="#ffffff" stroke="#c81e1e" stroke-width="9" stroke-linejoin="round"/>
    <rect x="-15" y="-13" width="30" height="15" rx="2" fill="#18181b"/>
    <rect x="-11" y="-10" width="8" height="7" fill="#ffffff"/>
    <rect x="1" y="-10" width="8" height="7" fill="#ffffff"/>
    <circle cx="-8" cy="1" r="3.5" fill="#18181b"/>
    <circle cx="8" cy="1" r="3.5" fill="#18181b"/>
    <path d="M -4,-13 L 0,-20 L 4,-13 Z" fill="#18181b"/>
  </g>`;
}

/**
 * A stop sign on its post: a plain red octagon, white border, no lettering —
 * the octagon SHAPE is what a driver who cannot read Amharic (or anything
 * else) recognises, exactly the reasoning behind every other sign here.
 */
function stopSign({ x, y, scale = 1 }) {
  const r = 27, k = 0.4142; // regular-octagon corner cut (tan(22.5°))
  const c = r * k;
  const pts = [
    [-c, -r], [c, -r], [r, -c], [r, c],
    [c, r], [-c, r], [-r, c], [-r, -c],
  ].map(([px, py]) => `${px},${py}`).join(' ');
  return `
  <g transform="translate(${x} ${y}) scale(${scale})">
    <rect x="-3" y="6" width="6" height="46" fill="#9ca3af" stroke="#6b7280" stroke-width="1.5"/>
    <polygon points="${pts}" fill="#c81e1e" stroke="#ffffff" stroke-width="4"/>
  </g>`;
}

/**
 * A traffic light on its post, drawn face-on like giveWaySign() rather than
 * from directly above — from overhead a signal head is just a dark rectangle
 * and the one thing that matters, WHICH lamp is lit, would be invisible.
 *
 * `lit` names the burning lamp; the other two are drawn dark, the way an
 * unlit lamp actually looks. No lettering, as with every sign in this app.
 */
function trafficLight({ x, y, lit = 'green', scale = 1 }) {
  const lamp = (cy, colour, on) =>
    `<circle cx="0" cy="${cy}" r="7.5" fill="${on ? colour : '#3f3f46'}" stroke="#18181b" stroke-width="1.5"/>`;
  return `
  <g transform="translate(${x} ${y}) scale(${scale})">
    <rect x="-3" y="0" width="6" height="42" fill="#9ca3af" stroke="#6b7280" stroke-width="1.5"/>
    <rect x="-14" y="-58" width="28" height="60" rx="6" fill="#27272a" stroke="#18181b" stroke-width="2"/>
    ${lamp(-43, '#dc2626', lit === 'red')}
    ${lamp(-28, '#f2b705', lit === 'amber')}
    ${lamp(-13, '#1f9d55', lit === 'green')}
  </g>`;
}

function tree({ x, y, r = 32 }) {
  return `<circle cx="${x}" cy="${y}" r="${r}" fill="#3f9142"/>`
       + `<rect x="${x - 5}" y="${y + r - 4}" width="10" height="22" fill="#6b4a2f"/>`;
}

/**
 * The single red lamp mounted beside a level crossing, warning of an
 * approaching train (book p.83: "עדשה אדומה מהבהבת"). Deliberately its own
 * primitive rather than trafficLight() with the other two lamps left dark —
 * a real crossing light is one lamp (sometimes a pair), never a red/amber/
 * green head, and drawing it as one keeps it from being misread as an
 * ordinary road signal that merely happens to be stuck on red.
 */
function crossingLight({ x, y, scale = 1 }) {
  // A single lamp on a bare post read as a map pin; a dark backing panel
  // behind two level red lamps fixed that and is where this settled — a
  // later attempt at a "beam" toward the approaching car read as a
  // megaphone bolted onto the sign and was dropped. Positioning (between
  // the barrier and the approaching car, close to the kerb) carries the
  // "facing traffic" idea instead, the same way every sign in this file
  // signals direction through placement, never through rotating the icon.
  return `
  <g transform="translate(${x} ${y}) scale(${scale})">
    <rect x="-4" y="0" width="8" height="30" fill="#71717a" stroke="#3f3f46" stroke-width="2"/>
    <rect x="-24" y="-30" width="48" height="26" rx="4" fill="#18181b" stroke="#000000" stroke-width="2"/>
    <circle cx="-11" cy="-17" r="9" fill="#dc2626" stroke="#7f1d1d" stroke-width="2"/>
    <circle cx="11" cy="-17" r="9" fill="#dc2626" stroke="#7f1d1d" stroke-width="2"/>
  </g>`;
}

/**
 * A level-crossing barrier arm, LOWERED — drawn as the driver actually sees
 * it: a red/white striped bar lying across the full width of the road,
 * blocking it, with a small dark post base at the verge end. Spans between
 * two y-coordinates rather than taking a single point, since (unlike a sign
 * or a light) the whole point of this element is that it stretches all the
 * way across the carriageway.
 */
function levelCrossingBarrier({ x, y0, y1, width = 14 }) {
  let stripes = '';
  let cy = y0, i = 0;
  const stripeH = 20;
  while (cy < y1) {
    const h = Math.min(stripeH, y1 - cy);
    stripes += `<rect x="${x - width / 2}" y="${cy}" width="${width}" height="${h}" fill="${i % 2 === 0 ? '#dc2626' : '#f8fafc'}"/>`;
    cy += h; i++;
  }
  return `
  <g stroke="#1f2937" stroke-width="2">
    ${stripes}
    <rect x="${x - width / 2 - 5}" y="${y1}" width="${width + 10}" height="14" fill="#3f3f46"/>
  </g>`;
}

/**
 * A building, seen from above as a roof — the only part of a building a
 * top-down scene actually shows. A flat rectangle would read as a car park
 * or a slab of pavement, so a centre ridge line is drawn on top of it to
 * read specifically as a pitched roof, the way tree() reads as a tree only
 * once the trunk is added.
 */
/**
 * A house — drawn face-on (peaked roof, wall, door, two windows), the same
 * reason signs and lights in this file are drawn face-on rather than from
 * directly above: a top-down roof is just a coloured rectangle, unreadable
 * as "a building" at this size. A pointed roof over a wall with a door is
 * the one silhouette that reads as a house at a glance, the same way
 * tree()'s trunk is what makes a plain circle read as a tree.
 *
 * (x, y) is the ground-level centre of the house; w/h are its total
 * footprint, kept identical in meaning to the flat rectangle this replaced
 * so every placement already checked clear of the road and of other
 * elements stays clear here too.
 */
function building({ x, y, w = 70, h = 46, wall = '#e7d9c0', roof = '#a63b12' }) {
  const roofH = h * 0.52, wallH = h - roofH;
  const top = y - h / 2, eave = top + roofH, ground = y + h / 2;
  const doorW = w * 0.2, doorH = wallH * 0.72;
  const winW = w * 0.17, winH = wallH * 0.4, winY = eave + wallH * 0.16;
  return `
  <g>
    <rect x="${x - w / 2}" y="${eave}" width="${w}" height="${wallH}" fill="${wall}" stroke="#6b4a2f" stroke-width="2"/>
    <polygon points="${x - w / 2 - 3},${eave} ${x + w / 2 + 3},${eave} ${x},${top}"
             fill="${roof}" stroke="#6b3510" stroke-width="2.5"/>
    <rect x="${x - w * 0.32}" y="${winY}" width="${winW}" height="${winH}" fill="#cfe8f5" stroke="#6b4a2f" stroke-width="1.5"/>
    <rect x="${x + w * 0.32 - winW}" y="${winY}" width="${winW}" height="${winH}" fill="#cfe8f5" stroke="#6b4a2f" stroke-width="1.5"/>
    <rect x="${x - doorW / 2}" y="${ground - doorH}" width="${doorW}" height="${doorH}" fill="#6b4a2f"/>
  </g>`;
}

/** A movement arrow. `priority` picks green "goes first" or red "must wait". */
function arrow({ d, priority = true }) {
  const col = priority ? C.go : C.wait;
  const mk  = priority ? 'headGo' : 'headWait';
  return `<path d="${d}" fill="none" stroke="${col}" stroke-width="11"
            stroke-linecap="round" stroke-linejoin="round" marker-end="url(#${mk})"/>`;
}

// ─── Scene: a plain four-way crossroads ───────────────────────────────────────

const W = 640, H = 440;
const RX = 238, RW = 164;          // vertical road
const RY = 150, RH = 164;          // horizontal road

const CENTRE_X = RX + RW / 2;      // 320
const CENTRE_Y = RY + RH / 2;      // 232

// Right-hand traffic: a car heading up keeps to the east half, one heading down
// to the west half, one heading left to the north half.
const NORTHBOUND_X = CENTRE_X + 40;
const SOUTHBOUND_X = CENTRE_X - 40;
const WESTBOUND_Y  = CENTRE_Y - 42;
const EASTBOUND_Y  = CENTRE_Y + 42;

function crossroads() {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <g fill="${C.road}">
    <rect x="${RX}" y="0" width="${RW}" height="${H}"/>
    <rect x="0" y="${RY}" width="${W}" height="${RH}"/>
  </g>
  <g fill="${C.kerb}">
    <rect x="${RX - 6}" y="0" width="6" height="${RY}"/><rect x="${RX + RW}" y="0" width="6" height="${RY}"/>
    <rect x="${RX - 6}" y="${RY + RH}" width="6" height="${H - RY - RH}"/><rect x="${RX + RW}" y="${RY + RH}" width="6" height="${H - RY - RH}"/>
    <rect x="0" y="${RY - 6}" width="${RX - 6}" height="6"/><rect x="${RX + RW + 6}" y="${RY - 6}" width="${W - RX - RW - 6}" height="6"/>
    <rect x="0" y="${RY + RH}" width="${RX - 6}" height="6"/><rect x="${RX + RW + 6}" y="${RY + RH}" width="${W - RX - RW - 6}" height="6"/>
  </g>
  <g stroke="${C.line}" stroke-width="4" stroke-dasharray="22 18">
    <line x1="${CENTRE_X}" y1="8" x2="${CENTRE_X}" y2="${RY - 10}"/>
    <line x1="${CENTRE_X}" y1="${RY + RH + 10}" x2="${CENTRE_X}" y2="${H - 8}"/>
    <line x1="8" y1="${CENTRE_Y}" x2="${RX - 10}" y2="${CENTRE_Y}"/>
    <line x1="${RX + RW + 10}" y1="${CENTRE_Y}" x2="${W - 8}" y2="${CENTRE_Y}"/>
  </g>
  ${tree({ x: 120, y: 80 })}${tree({ x: 520, y: 88, r: 28 })}
  ${tree({ x: 128, y: 372, r: 28 })}${tree({ x: 524, y: 366 })}`;
}

// ─── Scene: the same crossroads, sitting higher in the frame ──────────────────
//
// Identical to crossroads() except that the horizontal road is raised, which
// lengthens the southern approach from 126px to 172px. That extra room is not
// cosmetic: a signal head has to stand clear of the carriageway, and it is
// drawn upwards from its post, so with the junction at its usual height the
// head could never be placed AHEAD of a car waiting on the approach — the car
// simply filled the whole gap between the junction and the bottom edge.

const CR_HI_RY = 104;
const CR_HI_CENTRE_Y  = CR_HI_RY + RH / 2;   // 186
const CR_HI_WESTBOUND_Y = CR_HI_CENTRE_Y - 42;
const CR_HI_EASTBOUND_Y = CR_HI_CENTRE_Y + 42;

function crossroadsRaised() {
  const RB = CR_HI_RY + RH;                  // 268, south edge of the horizontal road
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <g fill="${C.road}">
    <rect x="${RX}" y="0" width="${RW}" height="${H}"/>
    <rect x="0" y="${CR_HI_RY}" width="${W}" height="${RH}"/>
  </g>
  <g fill="${C.kerb}">
    <rect x="${RX - 6}" y="0" width="6" height="${CR_HI_RY}"/><rect x="${RX + RW}" y="0" width="6" height="${CR_HI_RY}"/>
    <rect x="${RX - 6}" y="${RB}" width="6" height="${H - RB}"/><rect x="${RX + RW}" y="${RB}" width="6" height="${H - RB}"/>
    <rect x="0" y="${CR_HI_RY - 6}" width="${RX - 6}" height="6"/><rect x="${RX + RW + 6}" y="${CR_HI_RY - 6}" width="${W - RX - RW - 6}" height="6"/>
    <rect x="0" y="${RB}" width="${RX - 6}" height="6"/><rect x="${RX + RW + 6}" y="${RB}" width="${W - RX - RW - 6}" height="6"/>
  </g>
  <g stroke="${C.line}" stroke-width="4" stroke-dasharray="22 18">
    <line x1="${CENTRE_X}" y1="8" x2="${CENTRE_X}" y2="${CR_HI_RY - 10}"/>
    <line x1="${CENTRE_X}" y1="${RB + 10}" x2="${CENTRE_X}" y2="${H - 8}"/>
    <line x1="8" y1="${CR_HI_CENTRE_Y}" x2="${RX - 10}" y2="${CR_HI_CENTRE_Y}"/>
    <line x1="${RX + RW + 10}" y1="${CR_HI_CENTRE_Y}" x2="${W - 8}" y2="${CR_HI_CENTRE_Y}"/>
  </g>
  ${tree({ x: 112, y: 48, r: 28 })}${tree({ x: 540, y: 44, r: 30 })}
  ${tree({ x: 118, y: 388, r: 30 })}${tree({ x: 556, y: 380, r: 28 })}`;
}

// ─── Scene: a T junction ──────────────────────────────────────────────────────
//
// A different shape of junction, not another dressing of the crossroads: the
// side road ends at the main road instead of crossing it. It also settles a
// question a four-way crossroads leaves open — which road a sign belongs to.
// On the stem of a T the sign stands right beside the car it faces, on that
// car's own right-hand verge, and cannot be read as belonging to anything else.

const TEE_STEM_TOP = RY + RH;              // the side road starts at the main road

function teeJunction() {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <g fill="${C.road}">
    <rect x="0" y="${RY}" width="${W}" height="${RH}"/>
    <rect x="${RX}" y="${TEE_STEM_TOP}" width="${RW}" height="${H - TEE_STEM_TOP}"/>
  </g>
  <g fill="${C.kerb}">
    <rect x="0" y="${RY - 6}" width="${W}" height="6"/>
    <rect x="0" y="${RY + RH}" width="${RX - 6}" height="6"/>
    <rect x="${RX + RW + 6}" y="${RY + RH}" width="${W - RX - RW - 6}" height="6"/>
    <rect x="${RX - 6}" y="${TEE_STEM_TOP}" width="6" height="${H - TEE_STEM_TOP}"/>
    <rect x="${RX + RW}" y="${TEE_STEM_TOP}" width="6" height="${H - TEE_STEM_TOP}"/>
  </g>
  <g stroke="${C.line}" stroke-width="4" stroke-dasharray="22 18">
    <line x1="8" y1="${CENTRE_Y}" x2="${RX - 10}" y2="${CENTRE_Y}"/>
    <line x1="${RX + RW + 10}" y1="${CENTRE_Y}" x2="${W - 8}" y2="${CENTRE_Y}"/>
    <line x1="${CENTRE_X}" y1="${TEE_STEM_TOP + 12}" x2="${CENTRE_X}" y2="${H - 8}"/>
  </g>
  ${tree({ x: 108, y: 74 })}${tree({ x: 300, y: 66, r: 26 })}${tree({ x: 520, y: 78, r: 28 })}
  ${tree({ x: 96, y: 392, r: 30 })}${tree({ x: 552, y: 386, r: 26 })}`;
}

// ─── Scene: an open two-way road, no junction ─────────────────────────────────
//
// Overtaking is not a junction problem, so these cards drop the crossroads
// entirely. What matters instead is the pair of lines down the middle: Israeli
// marking puts a solid line and a broken line side by side, and the one NEAREST
// A DRIVER is the one that governs them: broken on their side, they may cross to
// overtake; solid on their side, they may not.
//
// `brokenLine` names which of the two is the broken one by where it sits in the
// picture, 'lower' or 'upper' — NOT by whose side it is on. A card may put the
// overtaking driver in either lane, and a flag named after "our side" silently
// means the opposite one as soon as it does.

const OPEN_RY = 130, OPEN_RH = 180;            // the carriageway: 130..310
const OPEN_CENTRE_Y = OPEN_RY + OPEN_RH / 2;   // 220
const ONCOMING_Y = OPEN_RY + 45;               // 175 — traffic coming towards us
const OURS_Y     = OPEN_RY + OPEN_RH - 45;     // 265 — our side, right-hand traffic
const NEAR_LINE_Y = OPEN_CENTRE_Y + 7;         // the lower of the two centre lines
const FAR_LINE_Y  = OPEN_CENTRE_Y - 7;         // the upper of the two

function openRoad({ brokenLine }) {
  const line = (y, broken) =>
    `<line x1="8" y1="${y}" x2="${W - 8}" y2="${y}" stroke="${C.line}" stroke-width="5"`
    + (broken ? ` stroke-dasharray="26 20"` : '') + `/>`;
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <rect x="0" y="${OPEN_RY}" width="${W}" height="${OPEN_RH}" fill="${C.road}"/>
  <g fill="${C.kerb}">
    <rect x="0" y="${OPEN_RY - 6}" width="${W}" height="6"/>
    <rect x="0" y="${OPEN_RY + OPEN_RH}" width="${W}" height="6"/>
  </g>
  ${line(FAR_LINE_Y, brokenLine === 'upper')}
  ${line(NEAR_LINE_Y, brokenLine === 'lower')}
  ${tree({ x: 90, y: 62, r: 30 })}${tree({ x: 300, y: 54, r: 26 })}${tree({ x: 540, y: 64, r: 28 })}
  ${tree({ x: 120, y: 384, r: 28 })}${tree({ x: 380, y: 392, r: 24 })}${tree({ x: 566, y: 380, r: 30 })}`;
}

// ─── Scene: the same road, one plain dashed centre line ───────────────────────
//
// Same carriageway, same kerb, same grass and trees as openRoad() — nothing
// invented. The only difference is a single dashed line (not openRoad()'s
// solid+broken overtaking pair, which has no business appearing on a card
// that isn't about overtaking) at `lineY`. A first version of this scene
// moved the line off true centre to buy extra height for OUR side — a user
// correctly rejected that too: a real two-way road's lanes are the same
// width, so the line belongs at the middle, same as parkedStreet() and
// levelCrossing() already put it. `lineY` stays a parameter only so a
// caller can pass OPEN_CENTRE_Y explicitly rather than this function
// hard-coding yet another name for the same constant.

function openRoadOneLine({ lineY }) {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <rect x="0" y="${OPEN_RY}" width="${W}" height="${OPEN_RH}" fill="${C.road}"/>
  <g fill="${C.kerb}">
    <rect x="0" y="${OPEN_RY - 6}" width="${W}" height="6"/>
    <rect x="0" y="${OPEN_RY + OPEN_RH}" width="${W}" height="6"/>
  </g>
  <line x1="8" y1="${lineY}" x2="${W - 8}" y2="${lineY}" stroke="${C.line}" stroke-width="5" stroke-dasharray="26 20"/>
  ${tree({ x: 90, y: 62, r: 30 })}${tree({ x: 300, y: 54, r: 26 })}${tree({ x: 540, y: 64, r: 28 })}
  ${tree({ x: 120, y: 384, r: 28 })}${tree({ x: 380, y: 392, r: 24 })}${tree({ x: 566, y: 380, r: 30 })}`;
}

// ─── Scene: a residential street with parked cars ──────────────────────────────
//
// A plain single dashed centre line, not the paired broken/solid lines
// openRoad() draws — that pairing is specifically the Israeli overtaking
// marking, and this card has nothing to do with overtaking. Drawing it here
// anyway would silently invite the question "can I pass here?", which is not
// what this street is teaching.

function parkedStreet() {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <rect x="0" y="${OPEN_RY}" width="${W}" height="${OPEN_RH}" fill="${C.road}"/>
  <g fill="${C.kerb}">
    <rect x="0" y="${OPEN_RY - 6}" width="${W}" height="6"/>
    <rect x="0" y="${OPEN_RY + OPEN_RH}" width="${W}" height="6"/>
  </g>
  <line x1="8" y1="${OPEN_CENTRE_Y}" x2="${W - 8}" y2="${OPEN_CENTRE_Y}" stroke="${C.line}" stroke-width="5" stroke-dasharray="26 20"/>
  <!-- Houses along both sides — the explanation calls this an urban street,
       but grass and trees alone read as open countryside. Placed in the
       gaps between and around the existing trees so nothing overlaps, and
       kept off the road entirely (only ever in the grass strips). -->
  ${building({ x: 24, y: 30, w: 44, h: 40, roof: '#a63b12' })}
  ${building({ x: 180, y: 28, w: 90, h: 44, roof: '#8a6a4a' })}
  ${building({ x: 420, y: 26, w: 100, h: 40, roof: '#a63b12' })}
  ${building({ x: 611, y: 32, w: 46, h: 40, roof: '#8a6a4a' })}
  ${tree({ x: 90, y: 62, r: 30 })}${tree({ x: 300, y: 54, r: 26 })}${tree({ x: 540, y: 64, r: 28 })}
  ${building({ x: 150, y: 382, w: 100, h: 46, roof: '#8a6a4a' })}
  ${building({ x: 350, y: 386, w: 90, h: 42, roof: '#a63b12' })}
  ${tree({ x: 566, y: 380, r: 30 })}`;
}

// ─── Scene: a road crossing a railway track ────────────────────────────────────
//
// Level 5's background: an ordinary straight road, exactly like openRoad(),
// with a railway track crossing it at a right angle further along. The
// track is drawn the full height of the frame — it does not stop at the
// road's edges, because a track that visibly continues on both sides is
// what makes it read as a railway crossing rather than a road marking.

function levelCrossing() {
  const trackX = 430;
  let sleepers = '';
  for (let sy = 4; sy < H; sy += 26) {
    sleepers += `<rect x="${trackX - 18}" y="${sy}" width="36" height="10" fill="#6b4a2f"/>`;
  }
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <rect x="0" y="${OPEN_RY}" width="${W}" height="${OPEN_RH}" fill="${C.road}"/>
  <g fill="${C.kerb}">
    <rect x="0" y="${OPEN_RY - 6}" width="${W}" height="6"/>
    <rect x="0" y="${OPEN_RY + OPEN_RH}" width="${W}" height="6"/>
  </g>
  <line x1="8" y1="${OPEN_CENTRE_Y}" x2="${W - 8}" y2="${OPEN_CENTRE_Y}" stroke="${C.line}" stroke-width="5" stroke-dasharray="26 20"/>
  ${sleepers}
  <rect x="${trackX - 19}" y="0" width="4" height="${H}" fill="#9ca3af"/>
  <rect x="${trackX + 15}" y="0" width="4" height="${H}" fill="#9ca3af"/>
  ${tree({ x: 90, y: 62, r: 30 })}${tree({ x: 560, y: 64, r: 26 })}
  ${tree({ x: 120, y: 384, r: 28 })}${tree({ x: 566, y: 380, r: 30 })}`;
}

// ─── Scene: the road ahead, seen from behind our own car ──────────────────────
//
// Not every situation reads from above. A motorcycle seen from directly
// overhead is mostly the rider's back, and three attempts at drawing one that
// way were still unrecognisable. From BEHIND it is unmistakable: the rider sits
// up, the helmet and the mirrors stand out, and the machine is obviously
// narrow. Same scene, same questions, different viewpoint.
//
// Depth is linear: t runs 0 at the horizon to 1 at the bottom of the picture,
// and everything — lane position and vehicle size — is interpolated on it.

const HORIZON = 150;
const VP_X = 320;                                    // vanishing point
const depthAt = y => (y - HORIZON) / (H - HORIZON);  // 0 far … 1 near
const lerp = (far, near, t) => far + (near - far) * t;

// road edges and the two centre lines, far value then near value
const EDGE_L = [298, 26], EDGE_R = [342, 614];
const MID_L  = [316, 292], MID_R = [324, 348];
const laneOurs     = t => lerp((MID_R[0] + EDGE_R[0]) / 2, (MID_R[1] + EDGE_R[1]) / 2, t);
const laneOncoming = t => lerp((EDGE_L[0] + MID_L[0]) / 2, (EDGE_L[1] + MID_L[1]) / 2, t);

function roadAhead({ brokenLine }) {
  const band = (a, b, fill, extra = '') =>
    `<path d="M ${a[0]},${HORIZON} L ${b[0]},${HORIZON} L ${b[1]},${H} L ${a[1]},${H} Z" fill="${fill}" ${extra}/>`;
  // a centre line drawn in perspective: solid as one band, broken as chunks
  const centreLine = (pair, broken) => {
    if (!broken) return band([pair[0] - 1.5, pair[1] - 3], [pair[0] + 1.5, pair[1] + 3], C.line);
    let out = '';
    for (let i = 0; i < 7; i++) {
      const t0 = Math.pow(i / 7, 1.7), t1 = Math.pow((i + 0.55) / 7, 1.7);
      const y0 = HORIZON + (H - HORIZON) * t0, y1 = HORIZON + (H - HORIZON) * t1;
      const x0 = lerp(pair[0], pair[1], t0), x1 = lerp(pair[0], pair[1], t1);
      const w0 = lerp(1.5, 3, t0), w1 = lerp(1.5, 3, t1);
      out += `<path d="M ${x0 - w0},${y0} L ${x0 + w0},${y0} L ${x1 + w1},${y1} L ${x1 - w1},${y1} Z" fill="${C.line}"/>`;
    }
    return out;
  };
  return `
  <rect width="${W}" height="${HORIZON}" fill="#bfe3f5"/>
  <rect y="${HORIZON}" width="${W}" height="${H - HORIZON}" fill="${C.grass}"/>
  ${band(EDGE_L, EDGE_R, C.road)}
  ${band([EDGE_L[0] - 2, EDGE_L[1] - 10], [EDGE_L[0] + 2, EDGE_L[1] + 10], C.kerb)}
  ${band([EDGE_R[0] - 2, EDGE_R[1] - 10], [EDGE_R[0] + 2, EDGE_R[1] + 10], C.kerb)}
  ${centreLine(MID_L, brokenLine === 'left')}
  ${centreLine(MID_R, brokenLine === 'lower' || brokenLine === 'right')}
  <circle cx="96" cy="${HORIZON - 26}" r="26" fill="#3f9142"/><rect x="91" y="${HORIZON - 6}" width="10" height="12" fill="#6b4a2f"/>
  <circle cx="556" cy="${HORIZON - 30}" r="30" fill="#3f9142"/><rect x="551" y="${HORIZON - 6}" width="10" height="14" fill="#6b4a2f"/>`;
}

/** A car seen from behind, sized by how far away it is. */
function carRear({ x, y, w, colour = 'white' }) {
  const { body, edge } = CARS[colour] ?? CARS.white;
  const h = w * 0.78, k = w / 100;
  return `
  <g transform="translate(${x} ${y}) scale(${k})">
    <rect x="-52" y="-30" width="14" height="34" rx="4" fill="${C.tyre}"/>
    <rect x="38"  y="-30" width="14" height="34" rx="4" fill="${C.tyre}"/>
    <path d="M -44,0 L -40,-52 C -38,-62 -30,-66 0,-66 C 30,-66 38,-62 40,-52 L 44,0 Z"
          fill="${body}" stroke="${edge}" stroke-width="3.5" stroke-linejoin="round"/>
    <path d="M -31,-52 C -30,-58 -24,-60 0,-60 C 24,-60 30,-58 31,-52 L 33,-30 L -33,-30 Z" fill="${C.glass}"/>
    <rect x="-44" y="-10" width="88" height="10" rx="3" fill="${edge}"/>
    <rect x="-38" y="-26" width="17" height="11" rx="3" fill="#ef4444"/>
    <rect x="21"  y="-26" width="17" height="11" rx="3" fill="#ef4444"/>
    <rect x="-14" y="-8"  width="28" height="7"  rx="2" fill="#e5e7eb"/>
  </g>`;
}

/**
 * A traffic light standing at the roadside AHEAD of us, in the rear view.
 *
 * This is the viewpoint a signal actually needs. Drawn on a plan, a signal
 * head is a dark rectangle with no direction: it cannot be made to "face"
 * the car it governs, and three attempts at placing one on a top-down
 * junction all failed for that reason. Seen from behind the wheel it faces
 * the viewer by construction, because the viewer is the driver it speaks to.
 *
 * `groundY` is where the post meets the ground, `h` the height to the top of
 * the head — both already in perspective, chosen by the scene.
 */
function trafficLightAhead({ x, groundY, h, lit = 'green' }) {
  const headH = h * 0.36, headW = headH * 0.46, r = headW * 0.27;
  const top = groundY - h;
  const lamp = (cy, colour, on) =>
    `<circle cx="${x}" cy="${cy}" r="${r}" fill="${on ? colour : '#3f3f46'}" stroke="#18181b" stroke-width="1.2"/>`;
  return `
  <rect x="${x - h * 0.022}" y="${top + headH}" width="${h * 0.044}" height="${h - headH}" fill="#9ca3af" stroke="#6b7280" stroke-width="1.2"/>
  <rect x="${x - headW / 2}" y="${top}" width="${headW}" height="${headH}" rx="${headW * 0.2}" fill="#27272a" stroke="#18181b" stroke-width="1.5"/>
  ${lamp(top + headH * 0.22, '#dc2626', lit === 'red')}
  ${lamp(top + headH * 0.50, '#f2b705', lit === 'amber')}
  ${lamp(top + headH * 0.78, '#1f9d55', lit === 'green')}`;
}

/**
 * A pedestrian crossing painted across the road, in the rear view: bars
 * running AWAY from the viewer, which is the same thing as running along the
 * direction of travel, spread across the width of the road. Each bar narrows
 * with distance, so the band reads as lying flat on the tarmac.
 */
function zebraAhead({ yFar, yNear, bars = 7 }) {
  const tF = depthAt(yFar), tN = depthAt(yNear);
  const lF = lerp(EDGE_L[0], EDGE_L[1], tF), rF = lerp(EDGE_R[0], EDGE_R[1], tF);
  const lN = lerp(EDGE_L[0], EDGE_L[1], tN), rN = lerp(EDGE_R[0], EDGE_R[1], tN);
  let out = '';
  for (let i = 0; i < bars; i++) {
    const a0 = (i + 0.18) / bars, a1 = (i + 0.82) / bars;
    out += `<path d="M ${lF + (rF - lF) * a0},${yFar} L ${lF + (rF - lF) * a1},${yFar}`
         + ` L ${lN + (rN - lN) * a1},${yNear} L ${lN + (rN - lN) * a0},${yNear} Z" fill="${C.line}"/>`;
  }
  return out;
}

/**
 * A person seen FROM THE SIDE, walking across in front of us — the only way
 * a pedestrian appears in a rear-view scene. Easier to read than the top-down
 * figure, because a human silhouette from the side is unmistakable: head,
 * shoulders, and legs caught mid-stride.
 *
 * Skin is a brown tone, as everywhere else in this app.
 */
function pedestrianSide({ x, groundY, h, colour = 'red', facing = 'left' }) {
  const { body } = CARS[colour] ?? CARS.red;
  const k = h / 100, skin = '#8a5a34', dir = facing === 'left' ? -1 : 1;
  return `
  <g transform="translate(${x} ${groundY}) scale(${dir * k} ${k})">
    <path d="M 0,-42 L -13,-2" stroke="#1f2937" stroke-width="9" stroke-linecap="round" fill="none"/>
    <path d="M 0,-42 L 14,-3"  stroke="#1f2937" stroke-width="9" stroke-linecap="round" fill="none"/>
    <path d="M -1,-72 L 15,-50" stroke="${skin}" stroke-width="7.5" stroke-linecap="round" fill="none"/>
    <rect x="-11" y="-78" width="22" height="38" rx="8" fill="${body}" stroke="#1f2937" stroke-width="2.5"/>
    <circle cx="1" cy="-88" r="11" fill="${skin}" stroke="#1f2937" stroke-width="2.5"/>
  </g>`;
}

/**
 * A motorcycle seen from behind, sized by how far away it is. From here the
 * things that identify it are unmissable — the rider sitting upright, the
 * helmet, the mirrors standing out either side, and a single narrow tyre.
 * The rider's hands and neck are a brown skin tone: the people using this app
 * are Ethiopian, and a default pink would be drawing somebody else.
 */
function motorcycleRear({ x, y, w, colour = 'green' }) {
  const { body, edge } = CARS[colour] ?? CARS.green;
  const k = w / 100, skin = '#8a5a34', jacket = '#1f2937';
  return `
  <g transform="translate(${x} ${y}) scale(${k})">
    <rect x="-13" y="-46" width="26" height="46" rx="8" fill="${C.tyre}"/>
    <path d="M -22,-52 C -22,-64 -14,-70 0,-70 C 14,-70 22,-64 22,-52 L 20,-40 L -20,-40 Z"
          fill="${body}" stroke="${edge}" stroke-width="3" stroke-linejoin="round"/>
    <rect x="-11" y="-58" width="22" height="12" rx="4" fill="#ef4444"/>
    <path d="M -30,-96 C -30,-112 -18,-122 0,-122 C 18,-122 30,-112 30,-96 L 26,-64 L -26,-64 Z"
          fill="${jacket}"/>
    <path d="M -30,-104 L -54,-88" stroke="${jacket}" stroke-width="15" stroke-linecap="round"/>
    <path d="M 30,-104 L 54,-88"  stroke="${jacket}" stroke-width="15" stroke-linecap="round"/>
    <circle cx="-56" cy="-86" r="8" fill="${skin}"/><circle cx="56" cy="-86" r="8" fill="${skin}"/>
    <line x1="-58" y1="-92" x2="-64" y2="-108" stroke="#4b5563" stroke-width="5"/>
    <line x1="58"  y1="-92" x2="64"  y2="-108" stroke="#4b5563" stroke-width="5"/>
    <ellipse cx="-66" cy="-112" rx="11" ry="8" fill="${C.glass}" stroke="#4b5563" stroke-width="3.5"/>
    <ellipse cx="66"  cy="-112" rx="11" ry="8" fill="${C.glass}" stroke="#4b5563" stroke-width="3.5"/>
    <rect x="-9" y="-134" width="18" height="16" fill="${skin}"/>
    <circle cx="0" cy="-146" r="26" fill="#e8edf3" stroke="#111827" stroke-width="4"/>
    <path d="M -22,-152 A 24,24 0 0 1 22,-152 Z" fill="#111827"/>
  </g>`;
}



/**
 * A pedestrian seen from above: head, shoulders and the arms swinging out from
 * them. What makes a person readable from overhead is the head sitting proud
 * of a much wider pair of shoulders, so those two shapes carry it and nothing
 * else is drawn. `heading` points the way they are walking.
 *
 * Skin is a brown tone: the people using this app are Ethiopian, and a default
 * pink would be drawing somebody else.
 */
function pedestrian({ x, y, heading = 0, colour = 'blue', scale = 1 }) {
  const { body } = CARS[colour] ?? CARS.blue;
  const skin = '#8a5a34';
  return `
  <g transform="translate(${x} ${y}) rotate(${heading}) scale(${scale})">
    <path d="M -13,-2 L -21,14" stroke="${skin}" stroke-width="7" stroke-linecap="round"/>
    <path d="M 13,-2 L 21,14"  stroke="${skin}" stroke-width="7" stroke-linecap="round"/>
    <path d="M -6,10 L -8,26" stroke="#1f2937" stroke-width="8" stroke-linecap="round"/>
    <path d="M 6,10  L 8,26"  stroke="#1f2937" stroke-width="8" stroke-linecap="round"/>
    <ellipse cx="0" cy="4" rx="14" ry="11" fill="${body}" stroke="#1f2937" stroke-width="2.5"/>
    <circle cx="0" cy="-6" r="9.5" fill="${skin}" stroke="#1f2937" stroke-width="2.5"/>
  </g>`;
}

/**
 * A motorcycle, seen from above like every vehicle in this file (car()'s
 * motorcycleRear() counterpart, for scenes that aren't from behind the
 * wheel). Two wheels in line front-to-back rather than a car's four
 * corners, a narrow body between them, handlebars, and a rider reduced to
 * a torso and a plain dark helmet — deliberately much narrower than
 * car()'s own silhouette, since that width difference is what makes "do
 * not ride alongside this" legible next to a full-width car.
 */
function motorcycle({ x, y, heading = 0, colour = 'blue', scale = 1 }) {
  const { body, edge } = CARS[colour] ?? CARS.blue;
  // First version overlapped the helmet onto the front wheel — both dark,
  // they fused into one blob with no visible wheel. Every dark part here
  // now sits with a clear gap from the next.
  //
  // The rider's jacket used to be a fixed mid grey regardless of `colour`
  // — the ONLY part that actually used `colour` was the thin 6px frame
  // stripe between the wheels, all but invisible at this scale, so the
  // motorcycle read as grey/black no matter what colour was passed, and a
  // user rightly flagged it as swallowed by the (also dark grey) road. The
  // jacket is the single largest shape here, so it now carries `colour`
  // instead — the wheels and helmet stay dark, which still keeps three
  // components (wheel, rider, wheel) reading as three, not one silhouette.
  return `
  <g transform="translate(${x} ${y}) rotate(${heading}) scale(${scale})">
    <rect x="-5" y="-38" width="10" height="12" rx="3" fill="${C.tyre}"/>
    <rect x="-3" y="-26" width="6" height="52" fill="${body}" stroke="${edge}" stroke-width="2"/>
    <rect x="-5" y="26" width="10" height="12" rx="3" fill="${C.tyre}"/>
    <path d="M -15,-19 L 15,-19" stroke="#3f3f46" stroke-width="4" stroke-linecap="round"/>
    <ellipse cx="0" cy="2" rx="9" ry="15" fill="${body}" stroke="${edge}" stroke-width="2"/>
    <circle cx="0" cy="-15" r="7.5" fill="#111827"/>
  </g>`;
}

/**
 * A traffic officer standing at a junction, directing traffic by hand.
 *
 * Deliberately NEVER rotated — same reason as pedestrian(): a rotated
 * person reads as an unreadable blob, not as "facing that way". Which car
 * gets which instruction is carried entirely by the arrows, exactly like
 * every other figure in this file; the officer itself only needs to read as
 * "a traffic officer", not as facing any particular direction.
 *
 * Arms held straight out to both sides (rather than pedestrian()'s relaxed
 * diagonal arms) is what makes this figure read as a person actively
 * directing traffic rather than a pedestrian standing still. A dark peaked
 * cap and a hi-vis (amber) body — reusing the same amber already used for
 * the amber lamp elsewhere — keep it visually distinct from both a
 * pedestrian and a car at a glance, without any lettering.
 */
function trafficOfficer({ x, y, scale = 1 }) {
  const skin = '#8a5a34';
  // Navy, not hi-vis amber: an amber vest reads as a road-works worker, not
  // specifically a police officer. Navy is what the cap and uniform below
  // are built to read as together.
  const uniform = '#1e3a5f';
  const uniformDark = '#0f2340';
  return `
  <g transform="translate(${x} ${y}) scale(${scale})">
    <path d="M -26,-2 L 26,-2" stroke="${skin}" stroke-width="8" stroke-linecap="round"/>
    <path d="M -7,11 L -9,28" stroke="#1f2937" stroke-width="9" stroke-linecap="round"/>
    <path d="M 7,11  L 9,28"  stroke="#1f2937" stroke-width="9" stroke-linecap="round"/>
    <ellipse cx="0" cy="5" rx="17" ry="13" fill="${uniform}" stroke="${uniformDark}" stroke-width="2.5"/>
    <circle cx="0" cy="-6" r="10.5" fill="${skin}" stroke="#1f2937" stroke-width="2.5"/>
    <!-- Peaked cap: dome, a light band, then a brim wider than the dome —
         the band-plus-brim silhouette is what reads as "police cap" rather
         than the plain dark dome the first version used. -->
    <path d="M -13,-13 A 13,12 0 0 1 13,-13 Z" fill="${uniformDark}"/>
    <rect x="-13" y="-14.5" width="26" height="3.5" fill="#e5e7eb"/>
    <ellipse cx="0" cy="-10.5" rx="16" ry="3.5" fill="${uniformDark}"/>
  </g>`;
}

/**
 * A zebra crossing painted across the carriageway, drawn from above.
 *
 * The stripes run ALONG the road, in the direction the traffic travels, and
 * each one is short. A first version drew them the other way round — long bars
 * lying across the lanes — which is not what the marking looks like on a real
 * road.
 */
function zebraCrossing({ cx, roadTop, roadBottom, length = 70 }) {
  const thickness = 12, gap = 10;
  let out = '';
  for (let y = roadTop + 6; y < roadBottom - thickness - 2; y += thickness + gap) {
    out += `<rect x="${cx - length / 2}" y="${y}" width="${length}" height="${thickness}" fill="${C.line}"/>`;
  }
  return out;
}

// ─── Scene: a T junction turned on its side ───────────────────────────────────
//
// Main road VERTICAL, side road running off to the EAST. The mirror of
// teeJunction(), and it exists for one reason: a crossing painted on this
// side road is crossed north-to-south, so the pedestrian figure can stay
// UPRIGHT and still face the way they are walking. On a vertical side road
// they would have to walk east or west, and the only ways to show that are to
// rotate the figure (which turns it into an unreadable blob) or to leave it
// facing the wrong way. Rotating the junction instead solves it at the root.
//
// The side road sits higher than RY so that there is a decent run of main
// road south of the junction for a turning car's arrow to start in.

const TEE_E_RY = 104, TEE_E_RH = 164;             // side road band: 104..268
const TEE_E_CENTRE_Y = TEE_E_RY + TEE_E_RH / 2;   // 186
const TEE_E_EASTBOUND_Y = TEE_E_CENTRE_Y + 42;    // 228 — our side, right-hand traffic
const TEE_E_STEM_LEFT = RX + RW;                  // 402 — where the side road begins

function teeJunctionEast() {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <g fill="${C.road}">
    <rect x="${RX}" y="0" width="${RW}" height="${H}"/>
    <rect x="${TEE_E_STEM_LEFT}" y="${TEE_E_RY}" width="${W - TEE_E_STEM_LEFT}" height="${TEE_E_RH}"/>
  </g>
  <g fill="${C.kerb}">
    <rect x="${RX - 6}" y="0" width="6" height="${H}"/>
    <rect x="${RX + RW}" y="0" width="6" height="${TEE_E_RY - 6}"/>
    <rect x="${RX + RW}" y="${TEE_E_RY + TEE_E_RH + 6}" width="6" height="${H - TEE_E_RY - TEE_E_RH - 6}"/>
    <rect x="${TEE_E_STEM_LEFT}" y="${TEE_E_RY - 6}" width="${W - TEE_E_STEM_LEFT}" height="6"/>
    <rect x="${TEE_E_STEM_LEFT}" y="${TEE_E_RY + TEE_E_RH}" width="${W - TEE_E_STEM_LEFT}" height="6"/>
  </g>
  <g stroke="${C.line}" stroke-width="4" stroke-dasharray="22 18">
    <line x1="${CENTRE_X}" y1="8" x2="${CENTRE_X}" y2="${TEE_E_RY - 10}"/>
    <line x1="${CENTRE_X}" y1="${TEE_E_RY + TEE_E_RH + 10}" x2="${CENTRE_X}" y2="${H - 8}"/>
    <line x1="${TEE_E_STEM_LEFT + 12}" y1="${TEE_E_CENTRE_Y}" x2="${W - 8}" y2="${TEE_E_CENTRE_Y}"/>
  </g>
  ${tree({ x: 74, y: 78, r: 30 })}${tree({ x: 152, y: 238, r: 26 })}${tree({ x: 84, y: 382, r: 28 })}
  ${tree({ x: 472, y: 48, r: 26 })}${tree({ x: 584, y: 58, r: 30 })}
  ${tree({ x: 480, y: 400, r: 30 })}${tree({ x: 596, y: 372, r: 26 })}`;
}

function svg(inner, label) {
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" role="img" aria-label="${label}">
  <defs>
    <marker id="headGo" viewBox="0 0 12 12" refX="9" refY="6" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
      <path d="M0,1 L11,6 L0,11 Z" fill="${C.go}"/>
    </marker>
    <marker id="headWait" viewBox="0 0 12 12" refX="9" refY="6" markerWidth="5" markerHeight="5" orient="auto-start-reverse">
      <path d="M0,1 L11,6 L0,11 Z" fill="${C.wait}"/>
    </marker>
  </defs>${inner}
</svg>
`;
}

// ─── Scene: a wider crossroads, two lanes each way on the vertical road ───────
//
// Used where the question is partly about WHICH LANE a manoeuvre starts from —
// a left turn has to begin from the lane nearest the centre line. Same road
// geometry conventions as crossroads(); only the vertical road is widened.

const VRX = 196, VRW = 248;                  // wide vertical road: 196..444
const LANE = VRW / 4;                        // 62
const SB_OUTER_X = VRX + LANE * 0.5;         // 227  southbound, kerb side
const SB_INNER_X = VRX + LANE * 1.5;         // 289  southbound, centre side
const NB_INNER_X = VRX + LANE * 2.5;         // 351  northbound, centre side — the left-turn lane
const NB_OUTER_X = VRX + LANE * 3.5;         // 413  northbound, kerb side

function crossroadsWide() {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <g fill="${C.road}">
    <rect x="${VRX}" y="0" width="${VRW}" height="${H}"/>
    <rect x="0" y="${RY}" width="${W}" height="${RH}"/>
  </g>
  <g fill="${C.kerb}">
    <rect x="${VRX - 6}" y="0" width="6" height="${RY}"/><rect x="${VRX + VRW}" y="0" width="6" height="${RY}"/>
    <rect x="${VRX - 6}" y="${RY + RH}" width="6" height="${H - RY - RH}"/><rect x="${VRX + VRW}" y="${RY + RH}" width="6" height="${H - RY - RH}"/>
    <rect x="0" y="${RY - 6}" width="${VRX - 6}" height="6"/><rect x="${VRX + VRW + 6}" y="${RY - 6}" width="${W - VRX - VRW - 6}" height="6"/>
    <rect x="0" y="${RY + RH}" width="${VRX - 6}" height="6"/><rect x="${VRX + VRW + 6}" y="${RY + RH}" width="${W - VRX - VRW - 6}" height="6"/>
  </g>
  <g stroke="${C.line}" stroke-width="4">
    <line x1="${CENTRE_X}" y1="8" x2="${CENTRE_X}" y2="${RY - 10}"/>
    <line x1="${CENTRE_X}" y1="${RY + RH + 10}" x2="${CENTRE_X}" y2="${H - 8}"/>
  </g>
  <g stroke="${C.line}" stroke-width="4" stroke-dasharray="22 18">
    <line x1="${VRX + LANE}" y1="8" x2="${VRX + LANE}" y2="${RY - 10}"/>
    <line x1="${VRX + LANE}" y1="${RY + RH + 10}" x2="${VRX + LANE}" y2="${H - 8}"/>
    <line x1="${VRX + LANE * 3}" y1="8" x2="${VRX + LANE * 3}" y2="${RY - 10}"/>
    <line x1="${VRX + LANE * 3}" y1="${RY + RH + 10}" x2="${VRX + LANE * 3}" y2="${H - 8}"/>
    <line x1="8" y1="${CENTRE_Y}" x2="${VRX - 10}" y2="${CENTRE_Y}"/>
    <line x1="${VRX + VRW + 10}" y1="${CENTRE_Y}" x2="${W - 8}" y2="${CENTRE_Y}"/>
  </g>
  ${tree({ x: 96, y: 76 })}${tree({ x: 552, y: 84, r: 28 })}
  ${tree({ x: 104, y: 376, r: 28 })}${tree({ x: 556, y: 370 })}`;
}

// ─── Scene: a wider crossroads, two lanes each way on the HORIZONTAL road ─────
//
// The mirror of crossroadsWide(). Used so that a left turn is not always drawn
// from the same approach: here the turning car arrives from the left of the
// picture and turns upward, which is a different manoeuvre to read even though
// the law behind it is the same.

const HRY = 96, HRH = 248;                   // wide horizontal road: 96..344
const HLANE = HRH / 4;                       // 62
const H_CENTRE_Y = HRY + HRH / 2;            // 220
const WB_OUTER_Y = HRY + HLANE * 0.5;        // 127  westbound, kerb side
const WB_INNER_Y = HRY + HLANE * 1.5;        // 189  westbound, centre side
const EB_INNER_Y = HRY + HLANE * 2.5;        // 251  eastbound, centre side — the left-turn lane
const EB_OUTER_Y = HRY + HLANE * 3.5;        // 313  eastbound, kerb side

function crossroadsWideAcross() {
  return `
  <rect width="${W}" height="${H}" fill="${C.grass}"/>
  <g fill="${C.road}">
    <rect x="0" y="${HRY}" width="${W}" height="${HRH}"/>
    <rect x="${RX}" y="0" width="${RW}" height="${H}"/>
  </g>
  <g fill="${C.kerb}">
    <rect x="0" y="${HRY - 6}" width="${RX - 6}" height="6"/><rect x="${RX + RW + 6}" y="${HRY - 6}" width="${W - RX - RW - 6}" height="6"/>
    <rect x="0" y="${HRY + HRH}" width="${RX - 6}" height="6"/><rect x="${RX + RW + 6}" y="${HRY + HRH}" width="${W - RX - RW - 6}" height="6"/>
    <rect x="${RX - 6}" y="0" width="6" height="${HRY}"/><rect x="${RX + RW}" y="0" width="6" height="${HRY}"/>
    <rect x="${RX - 6}" y="${HRY + HRH + 6}" width="6" height="${H - HRY - HRH - 6}"/><rect x="${RX + RW}" y="${HRY + HRH + 6}" width="6" height="${H - HRY - HRH - 6}"/>
  </g>
  <g stroke="${C.line}" stroke-width="4">
    <line x1="8" y1="${H_CENTRE_Y}" x2="${RX - 10}" y2="${H_CENTRE_Y}"/>
    <line x1="${RX + RW + 10}" y1="${H_CENTRE_Y}" x2="${W - 8}" y2="${H_CENTRE_Y}"/>
  </g>
  <g stroke="${C.line}" stroke-width="4" stroke-dasharray="22 18">
    <line x1="8" y1="${HRY + HLANE}" x2="${RX - 10}" y2="${HRY + HLANE}"/>
    <line x1="${RX + RW + 10}" y1="${HRY + HLANE}" x2="${W - 8}" y2="${HRY + HLANE}"/>
    <line x1="8" y1="${HRY + HLANE * 3}" x2="${RX - 10}" y2="${HRY + HLANE * 3}"/>
    <line x1="${RX + RW + 10}" y1="${HRY + HLANE * 3}" x2="${W - 8}" y2="${HRY + HLANE * 3}"/>
    <line x1="${CENTRE_X}" y1="8" x2="${CENTRE_X}" y2="${HRY - 10}"/>
    <line x1="${CENTRE_X}" y1="${HRY + HRH + 10}" x2="${CENTRE_X}" y2="${H - 8}"/>
  </g>
  ${tree({ x: 96, y: 46, r: 26 })}${tree({ x: 544, y: 44, r: 24 })}
  ${tree({ x: 100, y: 396, r: 24 })}${tree({ x: 548, y: 394, r: 26 })}`;
}

/**
 * The same numbered disc, but sitting ON the car rather than beside it.
 * A wide road pushes the verge too far from the vehicle for a badge there to
 * be unambiguous, and the official test diagrams label their vehicles the same
 * way. The white ring keeps it readable on a dark or a pale car alike.
 */
function badgeOnCar({ x, y, n }) {
  return `
  <g>
    <circle cx="${x}" cy="${y}" r="17" fill="${C.badge}" stroke="#ffffff" stroke-width="3"/>
    <text x="${x}" y="${y + 6}" font-family="Arial, Helvetica, sans-serif" font-size="19"
          font-weight="bold" fill="#ffffff" text-anchor="middle">${n}</text>
  </g>`;
}

// ─── Scenes ───────────────────────────────────────────────────────────────────

const SCENES = {};

// tr_l1_s3 / rd_l1_s1 — turning left across an oncoming car.
// Car 1 comes up from the south wanting to turn left. Car 2 comes down from the
// north going straight, and has priority. The two arrows deliberately cross:
// that intersection point is the whole reason car 1 must wait, and it is
// visible on screen.
SCENES.tr_l1_s3 = {
  name: 'tr_l1_s3_left_turn_vs_oncoming',
  label: 'Crossroads: a car turning left gives way to an oncoming car going straight',
  build: () => crossroads()
    + car({ x: NORTHBOUND_X, y: 368, heading: 0,   colour: 'yellow', indicate: 'left' })
    + car({ x: SOUTHBOUND_X, y: 96,  heading: 180, colour: 'blue' })
    // arrows before badges, so a badge is never buried under an arrow head
    + arrow({ d: `M ${SOUTHBOUND_X},150 L ${SOUTHBOUND_X},322`, priority: true })
    + arrow({
        d: `M ${NORTHBOUND_X},312 L ${NORTHBOUND_X},${WESTBOUND_Y + 34} `
         + `Q ${NORTHBOUND_X},${WESTBOUND_Y} ${NORTHBOUND_X - 44},${WESTBOUND_Y} `
         + `L 196,${WESTBOUND_Y}`,
        priority: false,
      })
    // badges sit on the verge beside their car, clear of arrows and bodywork
    + badge({ x: NORTHBOUND_X + 62, y: 368, n: 1 })
    + badge({ x: SOUTHBOUND_X - 62, y: 96,  n: 2 }),
};

// rd_l1_s2 — turning left with a third car arriving from the right.
//
// Same core rule as rd_l1_s1 (the left-turner gives way to oncoming traffic),
// but with a third vehicle so the learner meets a busier junction. Car 3 comes
// from the RIGHT, not the left, and that is a correctness decision rather than
// an aesthetic one: with a third car on the LEFT going straight, the three
// give-way duties form a closed loop (we yield to the oncoming car, the
// oncoming car yields to the car on its right, that car yields to us) and the
// law gives no entry order at all — the scene would have no correct answer.
// From the right the order is unambiguous, and both cars simply have priority
// over ours, which keeps the arrow vocabulary binary: green goes, red waits.
SCENES.rd_l1_s2 = {
  name: 'rd_l1_s2_left_turn_from_left_lane',
  label: 'Wide crossroads: a car turning left from the inner lane gives way to an oncoming car',
  build: () => crossroadsWideAcross()
    // The turn is deliberately drawn from a different approach to rd_l1_s1:
    // there the car came up from the bottom, here it arrives from the left and
    // turns upward. Same law, a picture the learner has to read afresh.
    // 0.88 so two cars sit side by side in adjacent lanes with visible air
    // between them; at full size they touch and read as one shape.
    + car({ x: 120, y: EB_INNER_Y, heading: 90,  colour: 'blue',   indicate: 'left', scale: 0.88 })
    + car({ x: 120, y: EB_OUTER_Y, heading: 90,  colour: 'silver', scale: 0.88 })
    + car({ x: 540, y: WB_INNER_Y, heading: 270, colour: 'yellow', scale: 0.88 })
    // arrows before badges, so a badge is never buried under an arrow head
    + arrow({ d: `M 480,${WB_INNER_Y} L 296,${WB_INNER_Y}`, priority: true })
    + arrow({ d: `M 176,${EB_OUTER_Y} L 474,${EB_OUTER_Y}`, priority: true })
    + arrow({
        d: `M 176,${EB_INNER_Y} L ${NORTHBOUND_X - 44},${EB_INNER_Y} `
         + `Q ${NORTHBOUND_X},${EB_INNER_Y} ${NORTHBOUND_X},${EB_INNER_Y - 44} `
         + `L ${NORTHBOUND_X},54`,
        priority: false,
      })
    + badgeOnCar({ x: 120, y: EB_INNER_Y, n: 1 })
    + badgeOnCar({ x: 540, y: WB_INNER_Y, n: 2 })
    + badgeOnCar({ x: 120, y: EB_OUTER_Y, n: 3 }),
};

SCENES.rd_l1_s3 = {
  name: 'rd_l1_s3_give_way_sign',
  label: 'T junction: a give-way sign makes the side-road car wait before turning right onto the main road',
  build: () => teeJunction()
    // The sign stands on the side road's own right-hand verge, level with the
    // car it faces, so there is no doubt which driver it is speaking to.
    + giveWaySign({ x: 442, y: 356, scale: 0.85 })
    + car({ x: NORTHBOUND_X, y: 392, heading: 0,  colour: 'green' })
    + car({ x: 140, y: EASTBOUND_Y, heading: 90,  colour: 'white' })
    // arrows before badges, so a badge is never buried under an arrow head
    // The side-road car turns RIGHT. Two cards already show a left turn, so the
    // manoeuvre here is a different one; what the card teaches is the sign, not
    // the turn. Its arrow runs a little south of the main-road arrow rather than
    // on top of it: the two are joining the same lane, and drawn on one line the
    // red arrowhead simply buried the green arrow and the picture stopped being
    // readable.
    // Both cars are heading into the same lane, so the arrows share its line.
    // They are separated ALONG that line, with the junction as the gap between
    // them: run them side by side and the red arrowhead simply covers the green
    // arrow. Read left to right the picture now says what actually happens —
    // the white car goes through first, the green car follows it out.
    + arrow({ d: `M 204,${EASTBOUND_Y} L 330,${EASTBOUND_Y}`, priority: true })
    + arrow({
        d: `M ${NORTHBOUND_X},344 L ${NORTHBOUND_X},${EASTBOUND_Y + 32} `
         + `Q ${NORTHBOUND_X},${EASTBOUND_Y} ${NORTHBOUND_X + 32},${EASTBOUND_Y} `
         + `L 468,${EASTBOUND_Y}`,
        priority: false,
      })
    + badge({ x: 296, y: 392, n: 1 })
    + badge({ x: 140, y: 212, n: 2 }),
};

SCENES.rd_l2_s1 = {
  name: 'rd_l2_s1_overtake_allowed',
  label: 'Open road: the broken line is on the side of the overtaking driver, so passing the slow vehicle is allowed',
  // This pair travels RIGHT TO LEFT along the far lane, while rd_l2_s2 and
  // rd_l2_s3 run left to right along the near one. Three cards that all showed
  // the same lane and the same direction let a learner recognise a picture
  // instead of reading a situation.
  build: () => openRoad({ brokenLine: 'upper' })
    + car({ x: 496, y: ONCOMING_Y, heading: 270, colour: 'silver' })
    // the vehicle being overtaken is drawn larger, so it reads as the slow one
    + car({ x: 252, y: ONCOMING_Y, heading: 270, colour: 'red', scale: 1.18 })
    + arrow({
        d: `M 432,${ONCOMING_Y} L 378,${ONCOMING_Y} `
         + `Q 334,${ONCOMING_Y} 334,${OURS_Y} `
         + `L 216,${OURS_Y} Q 176,${OURS_Y} 176,${ONCOMING_Y} `
         + `L 94,${ONCOMING_Y}`,
        priority: true,
      })
    + badge({ x: 496, y: ONCOMING_Y - 64, n: 1 })
    + badge({ x: 252, y: ONCOMING_Y - 68, n: 2 }),
};

SCENES.rd_l2_s2 = {
  name: 'rd_l2_s2_overtake_forbidden',
  label: 'Open road: the solid line is on our side, so the slow vehicle may not be overtaken',
  // Deliberately the same road as rd_l2_s1 with the two centre lines swapped.
  // The pair of cards differ in the one detail the rule actually turns on, so a
  // learner cannot answer them from the general look of the picture.
  build: () => openRoad({ brokenLine: 'upper' })
    + car({ x: 150, y: OURS_Y, heading: 90, colour: 'blue' })
    + car({ x: 392, y: OURS_Y, heading: 90, colour: 'yellow', scale: 1.18 })
    + arrow({
        d: `M 214,${OURS_Y} L 268,${OURS_Y} `
         + `Q 312,${OURS_Y} 312,${ONCOMING_Y} `
         + `L 430,${ONCOMING_Y} Q 470,${ONCOMING_Y} 470,${OURS_Y} `
         + `L 552,${OURS_Y}`,
        priority: false,
      })
    + badge({ x: 150, y: OURS_Y + 62, n: 1 })
    + badge({ x: 392, y: OURS_Y + 66, n: 2 }),
};

SCENES.rd_l2_s3 = {
  name: 'rd_l2_s3_overtake_two_wheeler',
  label: 'The road ahead: our car is behind a motorcycle and pulls right out to pass it',
  build: () => roadAhead({ brokenLine: 'lower' })
    + motorcycleRear({ x: laneOurs(depthAt(300)), y: 300, w: 56, colour: 'green' })
    // the path leaves our lane well before the rider and comes back only after
    // — squeezing past inside the lane is exactly what this card argues against
    + arrow({
        d: 'M 436,412 C 386,404 332,372 292,332 C 268,308 262,284 268,248',
        priority: true,
      })
    + carRear({ x: laneOurs(depthAt(420)), y: 420, w: 150, colour: 'white' })
    + badge({ x: 566, y: 388, n: 1 })
    + badge({ x: laneOurs(depthAt(300)) + 58, y: 286, n: 2 }),
};


SCENES.rd_l3_s1 = {
  name: 'rd_l3_s1_pedestrian_approaching_crossing',
  label: 'A pedestrian is walking towards the crossing, so the approaching car must slow and be ready to stop',
  // A city street rather than the open road of the overtaking cards: one lane
  // each way, a zebra across it, and no other vehicle. The only thing to read
  // here is the person, which is the whole point of the card.
  //
  // The person is WALKING ALONG THE PAVEMENT towards the crossing rather than
  // standing still at its mouth, and that is a legal point rather than a
  // cosmetic one. The regulation quoted in the MoT book (pp. 76-77) turns on
  // whether the pedestrian's intention to cross is EVIDENT, and the same book
  // lists what makes it evident: the direction the person is walking and the
  // pace they are walking at, read "before they ever step down into the road".
  // Somebody already halted at the kerb is only the narrowest version of that
  // test, so drawing them mid-approach teaches the rule at its true width.
  //
  // They are on the near pavement, the side the yellow car reaches first.
  build: () => openRoad({ brokenLine: 'lower' })
    + zebraCrossing({ cx: 330, roadTop: OPEN_RY, roadBottom: OPEN_RY + OPEN_RH })
    + car({ x: 128, y: OURS_Y, heading: 90, colour: 'yellow' })
    + pedestrian({ x: 214, y: 348, heading: 0, colour: 'red', scale: 1.15 })
    // The person's arrow carries their whole intended path: along the pavement
    // as far as the crossing, then over the road to the far side. Without that
    // second leg a walker beside a zebra reads as somebody merely passing it.
    + arrow({ d: `M 252,352 L 302,352 Q 330,352 330,316 L 330,112`, priority: true })
    + arrow({ d: `M 192,${OURS_Y} L 252,${OURS_Y}`, priority: false })
    + badge({ x: 128, y: OURS_Y + 62, n: 1 })
    + badge({ x: 214, y: 404, n: 2 }),
};

// rd_l3_s2 — turning right into a road a pedestrian is already crossing.
//
// A T junction rather than card 1's open road, and a TURN rather than
// straight travel: two of the five things this topic varies between cards
// are covered just by the change of layout. The pedestrian is drawn actually
// ON the crossing (bank question 0897, book p.80), not approaching it as in
// card 1 — a related but distinct moment: there the rule was about intent
// before anyone steps out, here it is the plainer case of someone already in
// the road the driver is about to enter.
//
// Our green car comes along the main road and turns right into the side
// road. Facing east, a right turn swings the car south into the stem — the
// same geometry already proven in rd_l1_s3, just reversed in direction and
// with a different destination (the stem, not the main road).
SCENES.rd_l3_s2 = {
  name: 'rd_l3_s2_pedestrian_crossing_turn',
  label: 'T junction: a car turning right must give way to a pedestrian already on the crossing it is turning into',
  build: () => teeJunctionEast()
    // The crossing sits well east of the junction, not jammed against it.
    // A first attempt at this scene put it at the very mouth of the side
    // road, which left the turning arrow nowhere to go: it bent downwards
    // and died inside the main road without ever entering the side road.
    + zebraCrossing({ cx: 520, roadTop: TEE_E_RY, roadBottom: TEE_E_RY + TEE_E_RH })
    + car({ x: NORTHBOUND_X, y: 380, heading: 0, colour: 'green' })
    // Walking north, and the figure is drawn upright, which is the direction
    // it faces. That agreement is the whole reason this card uses a sideways
    // junction: on a vertical side road the walk would be east-west and the
    // figure would have to be either rotated (unreadable) or wrong.
    // Standing in the eastbound lane itself — the very lane the car is trying
    // to turn into. Put them nearer the kerb and the two paths stop looking
    // like they meet, which is the only thing this picture has to say.
    + pedestrian({ x: 520, y: TEE_E_EASTBOUND_Y + 4, heading: 0, colour: 'blue', scale: 1.15 })
    + arrow({ d: `M 520,196 L 520,88`, priority: true })
    // The turn: north up the main road, then right into the side road, and
    // stopping short of the crossing. The arrow has to finish INSIDE the
    // side road for the manoeuvre to read as a turn at all.
    + arrow({
        d: `M ${NORTHBOUND_X},310 L ${NORTHBOUND_X},${TEE_E_EASTBOUND_Y + 34} `
         + `Q ${NORTHBOUND_X},${TEE_E_EASTBOUND_Y} ${NORTHBOUND_X + 34},${TEE_E_EASTBOUND_Y} `
         + `L 445,${TEE_E_EASTBOUND_Y}`,
        priority: false,
      })
    + badge({ x: 425, y: 380, n: 1 })
    + badge({ x: 520, y: 300, n: 2 }),
};

// rd_l3_s3 — a green light that does not mean "go".
//
// The busiest picture in the topic: three cars, a signal, a crossing and a
// pedestrian. Book p.71 carries both halves of the rule: "a driver shall not
// enter a junction that is not clear ... even if the light shows green", and
// "a driver approaching a signalised junction where pedestrians are crossing
// shall stop, to let them complete the crossing safely".
//
// TWO orientation problems decide this layout, and both were learned the hard
// way on earlier drafts of this same scene:
//
//  1. A signal head drawn face-on has no direction of its own on a plan. It
//     only reads as belonging to a particular driver when that driver is
//     travelling UP the picture and the head stands ahead of them on their
//     right — exactly where rd_l1_s3 puts its give-way sign. So OUR car runs
//     northbound. Every draft that had it running east left the signal
//     floating, apparently addressed to nobody.
//
//  2. The pedestrian figure cannot be rotated without turning into a blob, so
//     the crossing they use has to lie on a HORIZONTAL road, walked
//     north-south. Hence the crossing sits on the east arm, not on ours.
//
// Those two together give the scene its shape: we come up to the junction on
// a green, the car that stopped for the pedestrian on the east arm is stranded
// across the junction, and there is nowhere for us to go.
// This scene's key was originally rd_l3_s3, from when this card was still
// meant for the pedestrian level — it was moved to rd_l4_s1 after review
// (see the comment further up), but the SCENES key was never renamed to
// match. Left alone, a genuinely new rd_l3_s3 card later would silently
// overwrite this entry instead of erroring, which is exactly what a first
// attempt at that card did — the regression check kept "passing" because it
// was comparing this scene against itself.
SCENES.rd_l4_s1 = {
  name: 'rd_l3_s3_green_light_junction_not_clear',
  label: 'Signalised crossroads: our light is green, but a car stopped for a pedestrian is blocking the junction',
  build: () => crossroadsRaised()
    + zebraCrossing({ cx: 470, roadTop: CR_HI_RY, roadBottom: CR_HI_RY + RH })
    // Ahead of our car and on its right, the placement rd_l1_s3 settled for
    // a sign. Its whole head has to clear the kerb or it reads as an
    // obstacle standing in the carriageway.
    + trafficLight({ x: 424, y: 322, lit: 'green', scale: 0.78 })
    + car({ x: 140, y: CR_HI_EASTBOUND_Y, heading: 90, colour: 'blue' })
    // Stranded across the junction: it entered, then had to stop for the
    // person on the crossing beyond. This is what makes the junction "not
    // clear", and it is the reason our green light is worth nothing.
    + car({ x: 330, y: CR_HI_EASTBOUND_Y, heading: 90, colour: 'yellow' })
    + pedestrian({ x: 470, y: 204, heading: 0, colour: 'red', scale: 1.15 })
    + car({ x: NORTHBOUND_X, y: 376, heading: 0, colour: 'silver' })
    // Only the pedestrian gets an arrow. Our own car does not need one: a red
    // arrow over the car the question is about only says "this is you", which
    // the badge already says, and it crowded a picture that is busy enough.
    + arrow({ d: `M 470,168 L 470,78`, priority: true })
    + badgeOnCar({ x: NORTHBOUND_X, y: 342, n: 1 })
    + badgeOnCar({ x: 330, y: 204, n: 2 })
    + badgeOnCar({ x: 140, y: 204, n: 3 })
    + badgeOnCar({ x: 512, y: 176, n: 4 }),
};

// rd_l4_s2 — a green light does not turn a left turn into a protected one.
//
// Same junction and the same left-turn geometry as tr_l1_s3 (rd_l1_s1) —
// this card adds a signal on top of that unsignalised scene rather than
// replacing it, because the point being made is specifically about what a
// green light does and does not grant. Book p.63 already establishes that a
// left-turning driver gives way to oncoming traffic; book p.71 establishes
// that a driver at a signalised junction gives way to a pedestrian crossing
// there. A green ball resolves nothing between simultaneous permitted
// movements — it only says the junction may be entered — so both duties
// still apply once inside it.
//
// A third car, stopped on the crossing arm at its own red light, is in the
// picture for the reason the user asked for it: it makes the junction read
// as a real, busy, multi-directional signalised junction rather than a
// two-car diagram with a light bolted on. It carries no arrow and is not
// part of the question, the same way background cars work in rd_l3_s1.
// rd_l4_s2 — a signal that has failed, not one that is merely green.
//
// Rebuilt after review: the original version gave both directions of the
// through road a plain green ball at once, which is how ordinary permissive
// left turns work everywhere (the book's own left-turn-yields-to-oncoming
// rule, p.63, exists BECAUSE of exactly that setup) — but it asked the
// learner to accept two simultaneous greens on faith, and that reads as a
// contradiction before it reads as a rule. Book p.73 offers a cleaner, fully
// unambiguous version of the same lesson: a FLASHING amber (signal fault)
// hands control to whatever signs are posted, "as at a junction where
// give-way signs are posted", with pedestrians already crossing or clearly
// about to keeping their priority regardless. That removes the two-greens
// question entirely — only one sign here ever means "go".
//
// Our car faces a give-way sign: proceed once safe, which in this picture
// means once the pedestrian has finished. Both other cars face a stop sign
// each and are shown already stopped, so neither has an arrow — a stopped
// car with nothing left to decide does not need one, the same convention
// used for the blocked car in rd_l4_s1.
SCENES.rd_l4_s2 = {
  name: 'rd_l4_s2_signal_fault_give_way',
  label: 'Crossroads with a flashing amber signal fault: our car faces a give-way sign, the other two face a stop sign, and the pedestrian keeps priority over all of them',
  build: () => crossroads()
    + zebraCrossing({ cx: 140, roadTop: RY, roadBottom: RY + RH })
    // On our car's own right-hand verge, level with it — the placement
    // rule this topic has used for every sign since rd_l1_s3.
    + giveWaySign({ x: 440, y: 368, scale: 0.85 })
    // Facing car 2: its right-hand verge is the WEST side (facing south,
    // right is west), so the sign stands short of the road's west kerb.
    + stopSign({ x: 210, y: 96, scale: 0.85 })
    // Facing car 3: its right-hand verge is the NORTH side (facing west,
    // right is north). x=470 was tried first and failed a geometry check:
    // the sign's post ran down to within 3px of car 3's own roofline, close
    // enough to read as touching it. Moved further along the verge, ahead
    // of the car in its direction of travel, matching how every other sign
    // in this topic sits ahead of the car it faces rather than beside it.
    + stopSign({ x: 410, y: 95, scale: 0.85 })
    // A small flashing-amber head beside each sign, so the picture reads as
    // a real signal that has FAILED — not as a junction that simply never
    // had lights. One general light standing alone (tried first) had no
    // sign of its own to pair with and looked like an odd extra; three
    // small ones, each paired with the sign it now defers to, read clearly
    // as the same broken signal seen from each approach.
    + trafficLight({ x: 490, y: 405, lit: 'amber', scale: 0.55 })
    + trafficLight({ x: 170, y: 65,  lit: 'amber', scale: 0.55 })
    + trafficLight({ x: 460, y: 65,  lit: 'amber', scale: 0.55 })
    + car({ x: NORTHBOUND_X, y: 368, heading: 0, colour: 'white', indicate: 'left' })
    // Already stopped at its own sign, not mid-manoeuvre — no arrow.
    + car({ x: SOUTHBOUND_X, y: 96, heading: 180, colour: 'green' })
    + car({ x: 500, y: WESTBOUND_Y, heading: 270, colour: 'yellow' })
    + pedestrian({ x: 140, y: CENTRE_Y, heading: 0, colour: 'red', scale: 1.15 })
    // Our turn: identical path to tr_l1_s3's, because the manoeuvre itself
    // has not changed — only what is controlling the junction has.
    + arrow({
        d: `M ${NORTHBOUND_X},312 L ${NORTHBOUND_X},${WESTBOUND_Y + 34} `
         + `Q ${NORTHBOUND_X},${WESTBOUND_Y} ${NORTHBOUND_X - 44},${WESTBOUND_Y} `
         + `L 196,${WESTBOUND_Y}`,
        priority: false,
      })
    + badgeOnCar({ x: NORTHBOUND_X, y: 388, n: 1 })
    // On the car rather than beside it: car 2's own verge now carries its
    // stop sign, exactly where a beside-the-car badge would otherwise sit.
    + badgeOnCar({ x: SOUTHBOUND_X, y: 96, n: 2 })
    + badgeOnCar({ x: 500, y: 148, n: 3 })
    + badgeOnCar({ x: 140, y: 196, n: 4 }),
};

// rd_l3_s3 — a child hidden between parked cars, about to step out.
//
// Every other card in this level put the pedestrian somewhere the driver
// could already see them — approaching a crossing, on one, or on the road
// being turned into. Book p.79 teaches the opposite hazard: a pedestrian
// (the book specifically says "a pedestrian OR A CHILD") can be completely
// invisible until the last moment, because parked cars block the sightline.
// The lesson is not "who has right of way" — it is that a driver has to
// slow down and widen their gap from parked cars BEFORE anyone becomes
// visible at all, precisely because there is nothing yet to react to.
//
// Sources: book p.79 ("ליד כלי-רכב חונים" is listed among the places
// requiring special alertness; "להקטין את המהירות... לשמור רווח גדול יותר
// מכלי-רכב חונים") and bank questions 0892 / 0921 (their own wording for
// "what characterises this road" and "what danger must you allow for").
//
// A plain, single dashed centre line (parkedStreet(), not openRoad()) —
// this card has nothing to do with overtaking, and the paired broken/solid
// lines used for that topic would wrongly suggest it does.
SCENES.rd_l3_s3 = {
  name: 'rd_l3_s3_child_between_parked_cars',
  label: 'A residential street: a child is hidden between two parked cars, about to step into the road our car has not yet reached',
  build: () => parkedStreet()
    + car({ x: 280, y: 282, heading: 90, colour: 'silver', scale: 0.92 })
    + car({ x: 400, y: 282, heading: 90, colour: 'yellow', scale: 0.92 })
    + car({ x: 560, y: 282, heading: 90, colour: 'white', scale: 0.92 })
    // In the gap between the yellow and white cars — narrow enough that
    // only stepping fully clear of both would reveal them to a driver.
    // On the grass behind the parked row, not yet in the road at all —
    // the point is that a driver has nothing to react to yet. Small scale,
    // since the book specifically names a CHILD as the harder-to-see case.
    + pedestrian({ x: 480, y: 330, heading: 0, colour: 'red', scale: 0.65 })
    // Our own car, well back from the parked row — this is the moment
    // BEFORE the hazard is visible, which is the entire point of the card.
    + car({ x: 60, y: OURS_Y, heading: 90, colour: 'blue' })
    // A short green arrow, only long enough to read as "under way" — with
    // no arrow at all the first render of this scene left the blue car
    // looking like a fourth parked car rather than one approaching.
    + arrow({ d: `M 128,${OURS_Y} L 190,${OURS_Y}`, priority: true })
    // Only our car and the child are numbered — the three parked cars are
    // scenery a question never has to single out individually.
    + badgeOnCar({ x: 60, y: OURS_Y + 30, n: 1 })
    + badge({ x: 480, y: 358, n: 2 }),
};

// rd_l4_s3 — a traffic officer's hand signal overrides the traffic light.
//
// Book p.75 ("מדרג הציות" — the hierarchy of obedience): a police officer's
// instruction takes precedence over the traffic light, even when it
// contradicts it; the light in turn takes precedence over any sign. This is
// the one case in this level where a driver disregards a green light not
// because the junction is physically blocked (rd_l4_s1) and not because the
// signal itself has failed (rd_l4_s2), but because a human authority
// present at the junction has taken over completely.
//
// No pedestrian in this scene: level 3 already covers that ground, and a
// third kind of actor in every level-4 card would blur which single rule
// each one is actually testing.
SCENES.rd_l4_s3 = {
  name: 'rd_l4_s3_officer_overrides_green_light',
  label: 'Signalised crossroads: a traffic officer stands in the middle of the junction directing traffic. Our light is green, but the officer signals our car to stop, while waving a car on the crossing road through.',
  build: () => crossroads()
    // Our light is green — the whole point of the card is that this alone
    // means nothing once an officer is present. North verge, because
    // heading west makes north our car's right-hand side; these are the
    // same coordinates already proven clear of a car in this exact
    // position when rd_l4_s2 placed a sign here instead of a light.
    // All three approaches in view get their own light, showing an
    // ordinary, fully working signal pattern — not a fault. Car 1 and car 3
    // travel the same road in opposite directions, so both correctly show
    // green together; car 2 is on the crossing road, correctly red. Nothing
    // here contradicts anything else — the ONLY override in this picture is
    // the officer, which is the entire point.
    + trafficLight({ x: 410, y: 90, lit: 'green', scale: 0.8 })
    + car({ x: 500, y: WESTBOUND_Y, heading: 270, colour: 'blue' })
    // Stopping short of the junction despite the green light: the officer,
    // not the light, decides here.
    + arrow({ d: `M 500,${WESTBOUND_Y} L 420,${WESTBOUND_Y}`, priority: false })
    + badgeOnCar({ x: 500, y: WESTBOUND_Y, n: 1 })
    // West verge: heading south, right is west. Same coordinates already
    // proven clear of a car in this exact position, where rd_l4_s2 placed a
    // stop sign for this same car.
    + trafficLight({ x: 210, y: 96, lit: 'red', scale: 0.8 })
    // Not "green" — that colour is reserved for a lit green lamp elsewhere
    // in this picture, and a green CAR sitting at a RED light reads as a
    // mistake at a glance. Silver keeps car colour and lamp colour from
    // ever being confused with one another.
    + car({ x: SOUTHBOUND_X, y: 96, heading: 180, colour: 'silver' })
    // Waved through by the officer despite its own red light — the clearest
    // possible demonstration that the officer's gesture, not the lamp,
    // decides who moves.
    + arrow({ d: `M ${SOUTHBOUND_X},150 L ${SOUTHBOUND_X},330`, priority: true })
    + badgeOnCar({ x: SOUTHBOUND_X, y: 96, n: 2 })
    // A third, waiting car on the crossing road's other approach — the same
    // "this reads as a real, busy junction" reason rd_l4_s2 carries one.
    // No arrow: like every other background car in this topic, it is not
    // part of the question.
    + car({ x: 140, y: EASTBOUND_Y, heading: 90, colour: 'white' })
    + badgeOnCar({ x: 140, y: EASTBOUND_Y, n: 3 })
    // South verge: heading east, right is south. Pushed to y=388 (rather
    // than sitting just past the kerb at 320) so the head's own height
    // clears the kerb line by a comfortable margin — the same class of bug
    // rd_l4_s2's signs hit twice before that rule became standard practice.
    + trafficLight({ x: 220, y: 388, lit: 'green', scale: 0.75 })
    // Larger and shifted slightly east from the first version, both for
    // presence (user feedback: the figure needs to read as clearly there,
    // not incidental) and to keep clear of the green car's arrow at x=280
    // now that the wider figure's own bounding box reaches further left.
    + trafficOfficer({ x: 345, y: 235, scale: 1.5 })
    + badge({ x: 345, y: 297, n: 4 }),
};

// rd_l5_s1 — a level-crossing barrier that is down: stop, don't go round it.
//
// Level 5's first card, opening the "railway crossing" level of the agreed
// road_decisions plan (junctions → overtaking → pedestrians → signalised
// junctions → railway crossing → two-wheelers → stopping/parking).
//
// Source: book p.83 and its own official sample question on p.84 ("כיצד
// עליך לנהוג בהתקרבך למחסום משמאל כשהוא מורד?" — correct answer: stop
// before it and do not continue while it is moving or lowered). Kept to a
// single car for this first card of a new level, the same way tr_l1_s3 and
// rd_l3_s1 opened their own levels simply before later cards added more.
SCENES.rd_l5_s1 = {
  name: 'rd_l5_s1_barrier_lowered_stop',
  label: 'A road crossing a railway track. The level-crossing barrier is lowered, blocking the road, and a red warning light beside it is lit. Our car has stopped short of the barrier.',
  build: () => levelCrossing()
    + levelCrossingBarrier({ x: 380, y0: OPEN_RY - 6, y1: OPEN_RY + OPEN_RH + 6 })
    // Between the barrier and our car, pulled in as close to the kerb as
    // the panel's own height allows (about 3-4px clearance) — user
    // feedback asked for this twice, closer each time than every other
    // sign in this file.
    + crossingLight({ x: 330, y: 345, scale: 0.85 })
    + car({ x: 280, y: OURS_Y, heading: 90, colour: 'blue' })
    // Stops short of the barrier, not at it — the arrow ends with a visible
    // gap before the striped bar, the same way rd_l4_s2's give-way car
    // stopped with room in front of it rather than touching the line.
    + arrow({ d: `M 280,${OURS_Y} L 350,${OURS_Y}`, priority: false })
    + badgeOnCar({ x: 280, y: OURS_Y, n: 1 }),
};

// rd_l5_s2 — a level crossing with a STOP sign and no barrier.
//
// Book p.83's other stopping trigger: no barrier at all, only a stop sign
// posted before the crossing. The rule this card teaches is not "stop"
// alone (rd_l5_s1 already covers that) but the specific CHECK a driver must
// perform once stopped — turn off the radio, open the window, listen and
// look both ways along the track — before ever moving again. No train is
// drawn in the picture on purpose: the whole point of the rule is that the
// driver checks BEFORE knowing whether one is coming, the same reasoning
// rd_l3_s3 used to keep its hazard invisible until the last moment.
// Opposite lane, opposite direction and colour from rd_l5_s1 — travelling
// west on ONCOMING_Y rather than east on OURS_Y, so the two cards do not
// read as the same picture with one sign swapped for another. Right-hand
// verge flips with the direction: heading west, right is north, so the
// sign moves to the north verge instead of the south one.
SCENES.rd_l5_s2 = {
  name: 'rd_l5_s2_stop_sign_no_barrier',
  label: 'A road crossing a railway track, seen from the opposite direction to rd_l5_s1. There is no barrier here, only a stop sign on the near (north) verge before the track. Our yellow car has stopped short of the track.',
  build: () => levelCrossing()
    // North verge, ahead of our car (which is heading west) and short of
    // the track — the mirror image of rd_l5_s1's south-verge placement.
    + stopSign({ x: 490, y: 65, scale: 0.85 })
    + car({ x: 580, y: ONCOMING_Y, heading: 270, colour: 'yellow' })
    // Stops with a clear gap before the near rail, matching the book's "at
    // least four metres before the near rail" fallback rule.
    + arrow({ d: `M 580,${ONCOMING_Y} L 465,${ONCOMING_Y}`, priority: false })
    + badgeOnCar({ x: 580, y: ONCOMING_Y, n: 1 }),
};

// rd_l5_s3 — what a level crossing even is, and the general duty to check.
//
// Third and closing card of level 5. Unlike rd_l5_s1/s2, nothing here is
// actively stopping our car — no barrier, no lit warning light, no posted
// sign in view. That absence IS the point: the lesson is that a driver's
// own duty to look and listen does not depend on infrastructure being
// present at all. Book p.83's own list of stop triggers (a train seen or
// heard, a stop sign, a flashing red light, or a moving/closed barrier)
// and p.84's own definition question are the sources.
SCENES.rd_l5_s3 = {
  name: 'rd_l5_s3_what_is_a_crossing',
  label: 'A road crossing a railway track. The basic railway-crossing warning sign is posted, but no barrier and no lit warning light — nothing active is telling the driver what to do right now. Our silver car is still under way, approaching the crossing normally.',
  build: () => levelCrossing()
    // The basic crossing-designation sign every level crossing has by law
    // (book p.84's own definition) — distinct from the ACTIVE control
    // devices (barrier, flashing light, stop sign) this picture still has
    // none of. Right-hand verge, ahead of the car, before the track — the
    // same placement rule as every sign in this file.
    + railwayWarningSign({ x: 340, y: 365, scale: 0.85 })
    // Silver, not green — a green car sat almost invisibly under the
    // priority arrow's own matching green when first tried.
    + car({ x: 180, y: OURS_Y, heading: 90, colour: 'silver' })
    // Short "under way" arrow, starting clear of the car's own front edge
    // (car half-length 52, so 240 leaves an 8px gap) rather than on top of
    // it, and not a long run to the track — this picture does not resolve
    // whether it is safe to cross, only that the car is still moving
    // normally with nothing yet forcing a decision.
    + arrow({ d: `M 240,${OURS_Y} L 280,${OURS_Y}`, priority: true })
    + badgeOnCar({ x: 180, y: OURS_Y, n: 1 }),
};

// rd_l6_s1 — never ride alongside a two-wheeler in your own lane.
//
// First card of level 6 (two-wheelers), next in the agreed plan after
// railway crossings. Book p.82: a driver who catches up to a two-wheeler
// travelling in the same lane must never simply travel BESIDE it — either
// commit fully to overtaking it properly (moving into the other lane, same
// as overtaking a car), or drop back and follow until overtaking is safe.
// rd_l2_s3 already shows the MECHANICS of a safe pass; that is not this
// card's lesson. This picture shows the moment the rule is ABOUT, not its
// resolution: our car and a motorcycle genuinely side by side in the same
// lane, both still going straight, neither having moved over.
//
// Fitting a full-size car and a motorcycle side by side needs to make full
// use of OUR half of the carriageway. Three earlier attempts got this
// wrong, all caught by the user, not by me: two full vehicles squeezed in
// with the car itself nudged out of its ordinary position; then a
// fabricated "paved shoulder" with a painted boundary line that does not
// exist on any real road; then the real fix's own first try, which moved
// the centre line off true middle to buy extra room and quietly narrowed
// the oncoming lane in the process. The line stays exactly where every
// other openRoad-family scene puts it (OPEN_CENTRE_Y); the car and the
// motorcycle are simply sized to actually fit alongside each other in the
// space that leaves.
SCENES.rd_l6_s1 = {
  name: 'rd_l6_s1_no_riding_alongside',
  label: 'The same road as every other card, centre line included, nothing moved. Our blue car and a motorcycle travel genuinely side by side within our own lane, level with each other — the situation the rule is about, not yet resolved either way.',
  build: () => openRoadOneLine({ lineY: OPEN_CENTRE_Y })
    + car({ x: 300, y: 252, heading: 90, colour: 'blue' })
    // Same x as the car — truly parallel, not trailing behind it — offset
    // only in y, toward the kerb, with a clear gap so the two shapes never
    // actually touch even though they sit right beside each other.
    + motorcycle({ x: 300, y: 294.5, heading: 90, colour: 'yellow', scale: 0.7 })
    // Short and RED: still going straight, not yet moving over — this is
    // the wrong continuation the card is about, not a resolved manoeuvre.
    + arrow({ d: `M 352,252 L 400,252`, priority: false })
    + badgeOnCar({ x: 300, y: 252, n: 1 })
    + badge({ x: 300, y: 350, n: 2 }),
};

// rd_l6_s2 — hug the kerb, so a two-wheeler cannot sneak past on your right
// and turn right across it (the "right hook").
//
// Book p.82: because riders tend to ride the shoulder or overtake on the
// right, a driver — especially of a large vehicle — must drive as close as
// possible to the right-hand edge, precisely to stop a two-wheeler
// squeezing through there and overtaking illegally, both when driving
// straight and when turning right.
//
// A plain crossroads. Our car is travelling east, indicator already on for
// a right turn — but it is NOT hugging the kerb: a clear strip of empty
// road sits between it and the south kerb, exactly the gap the rule warns
// about. A motorcycle, further back on the same approach, is riding that
// gap along the kerb, about to draw level just as the car turns across it.
//
// A first version put the motorcycle directly beside/behind the car at a
// scale small enough to fit the leftover sliver of lane height — self-
// caught at the render stage as unreadable, a yellow smear half-swallowed
// by the car with no room to read as a separate vehicle. Separating the
// two ALONG the road instead of squeezing them into the same cross-section
// removes the constraint entirely: with no x-overlap, nothing can visually
// collide regardless of y, so the motorcycle can be drawn at a size that
// actually reads, while the empty strip beside the car still shows the gap
// on its own.
SCENES.rd_l6_s2 = {
  name: 'rd_l6_s2_hug_the_kerb_right_turn',
  label: 'A crossroads. Our black car, indicating right, is not close to the kerb — a clear gap of empty road sits between it and the south kerb. Behind it on the same approach, a red motorcycle rides that gap along the kerb, about to draw level as the car turns right across its path.',
  build: () => crossroads()
    // Black, not blue: a deliberately different colour pair from rd_l6_s1
    // (blue car / yellow motorcycle), so the two cards don't read as the
    // same picture at a glance.
    + car({ x: 170, y: 264, heading: 90, colour: 'black', indicate: 'right' })
    // Well back from the car in x, so nothing here depends on a tight y
    // gap — riding the kerb-side strip the car left open. No arrow of its
    // own: a short arrow drawn here landed its head right on the car,
    // reading as a collision rather than the motorcycle's own motion — the
    // car's turn arrow alone already carries the scene.
    + motorcycle({ x: 80, y: 295, heading: 90, colour: 'red', scale: 0.85 })
    // RED: the car's turn already under way, not a safe, resolved
    // manoeuvre — this is the execution the card is warning against.
    + arrow({ d: `M 224,264 L 248,264 Q 280,264 280,296 L 280,340`, priority: false })
    + badgeOnCar({ x: 170, y: 264, n: 1 })
    + badge({ x: 80, y: 340, n: 2 }),
};

// ─── Write SVG, then rasterise ────────────────────────────────────────────────

const sceneArg  = process.argv.indexOf('--scene');
const SCENE_KEY = sceneArg >= 0 ? process.argv[sceneArg + 1] : 'tr_l1_s3';
const chosen    = SCENES[SCENE_KEY];
if (!chosen) {
  console.error(`Unknown scene "${SCENE_KEY}". Known: ${Object.keys(SCENES).join(', ')}`);
  process.exit(1);
}

const outArg  = process.argv.indexOf('--out');
const OUT_DIR = outArg >= 0 ? process.argv[outArg + 1] : join(ROOT, 'temp_behavioral');
const NAME    = chosen.name;

const svgText = svg(chosen.build(), chosen.label);
const svgPath = join(OUT_DIR, `${NAME}.svg`);
writeFileSync(svgPath, svgText, 'utf8');
console.log(`SVG: ${svgPath}`);

// 2x so it stays crisp on a phone screen
const { loadImage, createCanvas } = require('canvas');
const img    = await loadImage(Buffer.from(svgText, 'utf8'));
const canvas = createCanvas(img.width * 2, img.height * 2);
canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
const png     = canvas.toBuffer('image/png');
const pngPath = join(OUT_DIR, `${NAME}.png`);
writeFileSync(pngPath, png);
console.log(`PNG: ${pngPath}  (${canvas.width}x${canvas.height}, ${(png.length / 1024).toFixed(1)} KB)`);
